package com.erudit.user.repository;
import com.erudit.user.model.SocialModels.*;import java.util.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository @RequiredArgsConstructor
public class SocialRepository {private final JdbcClient jdbc;
 public UUID request(UUID from,UUID to){return jdbc.sql("SELECT id FROM friend_requests WHERE requester_id=:from AND addressee_id=:to").param("from",from).param("to",to).query(UUID.class).optional().orElseGet(()->{UUID id=UUID.randomUUID();jdbc.sql("INSERT INTO friend_requests(id,requester_id,addressee_id,status) VALUES(:id,:from,:to,'PENDING')").param("id",id).param("from",from).param("to",to).update();return id;});}
 public void decide(UUID owner,UUID id,boolean accept){var requester=jdbc.sql("SELECT requester_id FROM friend_requests WHERE id=:id AND addressee_id=:owner AND status='PENDING'").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(()->new IllegalArgumentException("Request not found"));jdbc.sql("UPDATE friend_requests SET status=:status WHERE id=:id").param("status",accept?"ACCEPTED":"REJECTED").param("id",id).update();if(accept)jdbc.sql("INSERT INTO friendships(user_low,user_high) VALUES(LEAST(:requester,:owner),GREATEST(:requester,:owner)) ON CONFLICT DO NOTHING").param("requester",requester).param("owner",owner).update();}
 public List<PublicUser> friends(UUID user,int page,int size){return jdbc.sql("SELECT u.id,u.display_name FROM friendships f JOIN users u ON u.id=CASE WHEN f.user_low=:user THEN f.user_high ELSE f.user_low END WHERE f.user_low=:user OR f.user_high=:user ORDER BY u.display_name LIMIT :size OFFSET :offset").param("user",user).param("size",size).param("offset",page*size).query((r,n)->new PublicUser(r.getObject("id",UUID.class),r.getString("display_name"))).list();}
 public void remove(UUID user,UUID friend){jdbc.sql("DELETE FROM friendships WHERE user_low=LEAST(:user,:friend) AND user_high=GREATEST(:user,:friend)").param("user",user).param("friend",friend).update();}
 public Device saveDevice(UUID user,String token,String platform){return jdbc.sql("SELECT id FROM user_devices WHERE push_token=:token").param("token",token).query(UUID.class).optional().map(id->new Device(id,user,token,platform)).orElseGet(()->{var v=new Device(UUID.randomUUID(),user,token,platform);jdbc.sql("INSERT INTO user_devices(id,user_id,push_token,platform) VALUES(:id,:user,:token,:platform)").param("id",v.id()).param("user",user).param("token",token).param("platform",platform).update();return v;});}
 public void revokeDevice(UUID user,UUID id){jdbc.sql("DELETE FROM user_devices WHERE id=:id AND user_id=:user").param("id",id).param("user",user).update();}
 public InternalUser internal(UUID id){return jdbc.sql("SELECT display_name FROM users WHERE id=:id").param("id",id).query(String.class).optional().map(name->new InternalUser(id,name,true,jdbc.sql("SELECT id FROM user_devices WHERE user_id=:id ORDER BY id").param("id",id).query(UUID.class).list())).orElseThrow(()->new IllegalArgumentException("User not found"));}
}
